+
+    private static void parseMultiLine(ByteBuffer byteBuffer, boolean hasZ, StringBuilder sb) {
+        sb.append("MULTILINESTRING").append(SPACE);
+        final int numLines = byteBuffer.getInt();
+        if (numLines == 0) {
+            sb.append(EMPTY);
+            return;
+        }
+        sb.append(LPAREN);
+        for (int i = 0; i < numLines; i++) {
